python3 - <<'E'
p='src/orders.js'
s=open(p).read()
s=s.replace('import { priceCart }','import { formatCents } from "./money.js";\nimport { priceCart }')
s+='''
/** The receipt line for one cart line: its sku and quantity. */
function lineText({ sku, quantity }) {
  return `${sku} x${quantity}`;
}

/** The discount receipt line, or no lines at all when the order has no discount. */
function discountLines(order, currency) {
  return order.discount > 0 ? [`Discount: ${formatCents(order.discount, currency)}`] : [];
}

/**
 * A printable multi-line receipt for an order: one line per cart line, then subtotal,
 * discount (only when there is one), tax, shipping with its tier, and total,
 * with amounts formatted like "USD 12.50".
 */
export function receipt(order, currency) {
  return [
    ...order.lines.map(lineText),
    `Subtotal: ${formatCents(order.subtotal, currency)}`,
    ...discountLines(order, currency),
    `Tax: ${formatCents(order.tax, currency)}`,
    `Shipping (${order.shipping.tier}): ${formatCents(order.shipping.cost, currency)}`,
    `Total: ${formatCents(order.total, currency)}`,
  ].join("\\n");
}
'''
open(p,'w').write(s)
p='test/orders.test.js'
s=open(p).read()
s=s.replace('import { placeOrder }','import { placeOrder, receipt }')
s+='''
const sampleOrder = {
  lines: [
    { sku: "MUG", quantity: 2 },
    { sku: "DESK", quantity: 1 },
  ],
  subtotal: 27400,
  discount: 500,
  tax: 1950,
  shipping: { tier: "freight-express", cost: 5400 },
  total: 34250,
};

test("a receipt lists each line, the discount, and every amount as currency", () => {
  assert.equal(
    receipt(sampleOrder, "USD"),
    [
      "MUG x2",
      "DESK x1",
      "Subtotal: USD 274.00",
      "Discount: USD 5.00",
      "Tax: USD 19.50",
      "Shipping (freight-express): USD 54.00",
      "Total: USD 342.50",
    ].join("\\n"),
  );
});

test("a receipt omits the discount line when the order has no discount", () => {
  assert.doesNotMatch(receipt({ ...sampleOrder, discount: 0 }, "USD"), /Discount/);
});
'''
open(p,'w').write(s)
p='README.md'
s=open(p).read()
s=s.replace('into an order record.','into an order record; `receipt` renders an order as printable text.')
open(p,'w').write(s)
E
